package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Loading is strict: a missing file, a missing required key, an unknown key or a value that cannot be used
 * makes {@link #load} throw a {@link ConfigException} that lists every problem found. Defaults are only applied
 * to optional keys that are absent from the file, never as a substitute for an invalid value.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    static final String UPSTREAM_URL = "upstream.url";
    static final String API_TOKEN = "api.token";
    static final String WORKER_THREADS = "worker.threads";
    static final String QUEUE_CAPACITY = "queue.capacity";
    static final String RETRY_ATTEMPTS = "retry.max-attempts";
    static final String REQUEST_TIMEOUT = "request.timeout";
    static final String METRICS_ENABLED = "metrics.enabled";

    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_ATTEMPTS, REQUEST_TIMEOUT, METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        Parser parser = new Parser(properties);
        ServiceConfig config = new ServiceConfig(
                parser.upstream(),
                parser.required(API_TOKEN),
                parser.intValue(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                parser.intValue(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                parser.intValue(RETRY_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                parser.duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                parser.bool(METRICS_ENABLED, false));
        parser.rejectUnknownKeys();
        if (!parser.errors.isEmpty()) {
            StringBuilder message = new StringBuilder("invalid configuration in ").append(file).append(':');
            for (String error : parser.errors) {
                message.append(System.lineSeparator()).append("  - ").append(error);
            }
            throw new ConfigException(message.toString());
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("configuration file " + file.toAbsolutePath() + " does not exist");
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read configuration file " + file.toAbsolutePath() + ": " + e);
        }
        return properties;
    }

    /** Parses individual keys, collecting every problem instead of stopping at the first. */
    private static final class Parser {
        private final Properties properties;
        private final List<String> errors = new ArrayList<>();

        Parser(Properties properties) {
            this.properties = properties;
        }

        private String raw(String key) {
            String value = properties.getProperty(key);
            return value == null ? null : value.trim();
        }

        String required(String key) {
            String value = raw(key);
            if (value == null || value.isEmpty()) {
                errors.add(key + " is required");
                return null;
            }
            return value;
        }

        URI upstream() {
            String value = required(UPSTREAM_URL);
            if (value == null) {
                return null;
            }
            try {
                URI uri = new URI(value);
                String scheme = uri.getScheme();
                if (scheme == null
                        || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                        || uri.getHost() == null) {
                    errors.add(UPSTREAM_URL + " must be an absolute http or https URL with a host, but was \""
                            + value + "\"");
                    return null;
                }
                return uri;
            } catch (URISyntaxException e) {
                errors.add(UPSTREAM_URL + " is not a valid URL (\"" + value + "\"): " + e.getReason());
                return null;
            }
        }

        int intValue(String key, int defaultValue, int minimum) {
            String value = raw(key);
            if (value == null) {
                return defaultValue;
            }
            try {
                int parsed = Integer.parseInt(value);
                if (parsed < minimum) {
                    errors.add(key + " must be at least " + minimum + ", but was " + parsed);
                    return defaultValue;
                }
                return parsed;
            } catch (NumberFormatException e) {
                errors.add(key + " must be a whole number of at least " + minimum + ", but was \"" + value + "\"");
                return defaultValue;
            }
        }

        Duration duration(String key, Duration defaultValue) {
            String value = raw(key);
            if (value == null) {
                return defaultValue;
            }
            Matcher matcher = DURATION.matcher(value);
            String expected = key + " must be a whole number followed by ms, s or m (for example 30s), but was \""
                    + value + "\"";
            if (!matcher.matches()) {
                errors.add(expected);
                return defaultValue;
            }
            try {
                long amount = Long.parseLong(matcher.group(1));
                Duration parsed = switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
                if (parsed.isZero()) {
                    errors.add(key + " must be greater than zero, but was \"" + value + "\"");
                    return defaultValue;
                }
                parsed.toMillis(); // the relay works in milliseconds; reject values that do not fit
                return parsed;
            } catch (ArithmeticException | NumberFormatException e) {
                errors.add(key + " is too large: \"" + value + "\"");
                return defaultValue;
            }
        }

        boolean bool(String key, boolean defaultValue) {
            String value = raw(key);
            if (value == null) {
                return defaultValue;
            }
            if (value.equalsIgnoreCase("true")) {
                return true;
            }
            if (value.equalsIgnoreCase("false")) {
                return false;
            }
            errors.add(key + " must be true or false, but was \"" + value + "\"");
            return defaultValue;
        }

        void rejectUnknownKeys() {
            for (String key : new TreeSet<>(properties.stringPropertyNames())) {
                if (!KNOWN_KEYS.contains(key)) {
                    errors.add("unknown key \"" + key + "\" (known keys: " + String.join(", ", new TreeSet<>(KNOWN_KEYS))
                            + ")");
                }
            }
        }
    }
}

